    identity = codomain.identity

    def _image(r):
        if r.is_identity:
            return identity
        else:
            w = identity
            r_arr = r.array_form
            i = 0
            j = 0
            # i is the index for r and j is for
            # r_arr. r_arr[j] is the tuple (sym, p)
